 static Main23FirstPlayableQA(){EditorApplication.playModeStateChanged+=s=>{if(s!=PlayModeStateChange.EnteredPlayMode||!SessionState.GetBool(Key,false))return;Directory.CreateDirectory(Output);Application.runInBackground=true;UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;UnityEngine.InputSystem.InputSystem.settings.editorInputBehaviorInPlayMode=UnityEngine.InputSystem.InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;foreach(var device in UnityEngine.InputSystem.InputSystem.devices.ToArray())if(device is UnityEngine.InputSystem.Keyboard||device is UnityEngine.InputSystem.Mouse)UnityEngine.InputSystem.InputSystem.DisableDevice(device);UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>("Main23VirtualKeyboard");UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>("Main23VirtualMouse");AudioListener.volume=0;Application.targetFrameRate=60;QualitySettings.vSyncCount=0;GameSaveService.AuditSaveDirectory=Path.Combine(Root,"Saves");UserSettingsService.BeginAudit(Path.Combine(Root,"Settings"));UserSettingsService.SetMuteAll(true);Application.logMessageReceived+=(t,st,k)=>{if(k==LogType.Error||k==LogType.Exception||k==LogType.Assert){if(st.Contains("UnityEditor.Search"))File.AppendAllText(Path.Combine(Output,"editor_search_errors.txt"),t+"\n"+st+"\n");else if(expectedSaveFailure)File.AppendAllText(Path.Combine(Output,"expected_save_errors.txt"),t+"\n");else errors.Add(t+"\n"+st);}};routine=Flatten(Extra?RunExtras():Run());deadline=EditorApplication.timeSinceStartup+600;EditorApplication.update+=Tick;};}
 public static void Start(){if(!Application.isBatchMode||!Application.dataPath.Replace('\\','/').Contains("/Temp/Main23FirstPlayable20261023/Worktree/Unity/Client/Assets"))throw new Exception("격리 Main23 경로만 허용합니다.");Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void Check(bool ok,string name){checks.Add((ok?"PASS|":"FAIL|")+name);File.WriteAllLines(Path.Combine(Output,"checks.txt"),checks);if(!ok)throw new Exception(name);}
 static PlayerController Player=>Object.FindAnyObjectByType<PlayerController>();
 static IEnumerator Wait(float t){float end=Time.realtimeSinceStartup+t;while(Time.realtimeSinceStartup<end)yield return null;}
 static IEnumerator Load(string scene){var op=SceneManager.LoadSceneAsync(scene);while(!op.isDone)yield return null;yield return Wait(.6f);}
 static IEnumerator Until(Func<bool> condition,string label,float timeout=12){float end=Time.realtimeSinceStartup+timeout;while(!condition()&&Time.realtimeSinceStartup<end)yield return null;Check(condition(),label);}
 static Main23Site Site(Main23Site.Kind kind)=>Object.FindObjectsByType<Main23Site>(FindObjectsSortMode.None).Single(x=>x.SiteKind==kind);
 static void At(Vector2 pos){Player.transform.position=pos;var rb=Player.GetComponent<Rigidbody2D>();rb.position=pos;rb.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 static IEnumerator Walk(Main23Site site,string label){var travel=Object.FindAnyObjectByType<Main23MouseTravel>();Check(travel.GoTo(site),label+".RouteFound");yield return Until(()=>!travel.IsTravelling,label+".Arrived",16);Check(Vector2.Distance(Player.transform.position,site.transform.position)<Main23Site.Range,label+".WithinInteractionRadius position="+Player.transform.position+" target="+site.transform.position);}
 static IEnumerator Close(){var d=ProjectLimitless.UI.DialoguePresenter.Instance;for(int i=0;i<40&&d!=null&&d.IsOpen;i++){d.Advance();yield return Wait(.04f);}yield return Wait(.08f);Check(d!=null&&!d.IsOpen,"Dialogue.Closed");}
 static IEnumerator Choose(Main23Site site,int choice,string label){Check(site.TryInteract(),label+".OpenedChoice");yield return Wait(.08f);var panel=Object.FindAnyObjectByType<Main21ChoicePanel>();Check(panel!=null,label+".ActualChoicePanel");panel.Select(choice);yield return Wait(.8f);}
