  var testimony=JsonUtility.FromJson<GameSaveData>(File.ReadAllText(Path.Combine(Root,"Checkpoint_Testimony.json")));GameSaveService.RestoreSession(1,testimony);yield return Load(testimony.CurrentSceneId);At(Vector2.zero);yield return Wait(.2f);Checkpoint("DeltaBeforeFailure");string realSaveDirectory=GameSaveService.AuditSaveDirectory;string blocked=Path.Combine(Root,"BlockedSaveDirectory");File.WriteAllText(blocked,"QA write failure fixture");GameSaveService.AuditSaveDirectory=blocked;expectedSaveFailure=true;
  yield return Choose(Site(Main23Site.Kind.Checkpoint),0,"WriteFailure.Register");Check(Chapter3Main23Flow.Completed,"WriteFailure.MemoryCompletedExistingSemantics");Check(Object.FindObjectsByType<Text>(FindObjectsSortMode.None).Any(t=>t.text.Contains("저장에 실패")),"WriteFailure.VisibleRetryMessage");yield return Close();expectedSaveFailure=false;GameSaveService.AuditSaveDirectory=realSaveDirectory;
  Check(GameSaveService.TryLoadSlot(1,out var disk),"WriteFailure.PreviousDiskReadable");GameSaveService.RestoreSession(1,disk);Check(Chapter3Main23Flow.Step==4&&!Chapter3Main23Flow.Completed,"WriteFailure.DiskRemainsBeforeCompletion");yield return Load(disk.CurrentSceneId);At(Vector2.zero);yield return Wait(.2f);yield return Choose(Site(Main23Site.Kind.Checkpoint),0,"WriteRetry.Register");yield return Close();Checkpoint("DeltaRetryCompleted");yield return Continue("DeltaRetryCompleted");yield return Wait(.3f);Check(Chapter3Main23Flow.Completed,"WriteRetry.PersistedCompletion");
