  Check(!Site(Main23Site.Kind.TraceA).TryInteract(),"TraceA.DuplicateRejected");Checkpoint("OneTrace");yield return Continue("OneTrace");yield return Wait(.3f);Check(Chapter3Main23Flow.ClueCount==1&&Chapter3Main23Flow.Step==1,"Continue.OneTracePreserved");
  yield return Walk(Site(Main23Site.Kind.TraceB),"Wheelchair.CartTrace");yield return Press(UnityEngine.InputSystem.Key.F);Check(ProjectLimitless.UI.DialoguePresenter.Instance.IsOpen,"Keyboard.F.TraceB.Open");yield return Close();Check(Chapter3Main23Flow.Step==2&&Main23Progress.Flags==3,"Goal2.TwoDistinctTraces");CaptureCameraUI("F1_TwoTraces_UnityCameraUI");
  yield return Walk(Site(Main23Site.Kind.NorthGate),"Wheelchair.NorthGate");yield return Choose(Site(Main23Site.Kind.NorthGate),0,"Gate.EnterVillage");yield return Until(()=>SceneManager.GetActiveScene().name==Chapter3Main23Flow.Village&&Player!=null,"Village.Loaded");yield return Wait(.8f);
  Check(Chapter3Main23Flow.Step==3&&Vector2.Distance(Player.transform.position,new Vector2(0,-8))<.2f,"Goal3.ValidArrivalSpawn");Check(!WorldModalState.IsOpen,"Arrival.NoForcedDialogue");Checkpoint("Arrival");yield return Continue("Arrival");yield return Wait(.5f);Check(Chapter3Main23Flow.Step==3,"Continue.Arrival");
  Check(!Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Any(x=>x.GetType().Name=="FieldMonsterSpawnRuntime"),"Village.NoMonsters");
  Check(Object.FindObjectsByType<SceneTransitionTrigger>(FindObjectsSortMode.None).Length==0,"Village.NoAutomaticF2OrEastTransition");
  yield return Walk(Site(Main23Site.Kind.Guide),"Wheelchair.Guide");yield return Press(UnityEngine.InputSystem.Key.E);Check(ProjectLimitless.UI.DialoguePresenter.Instance.IsOpen,"Keyboard.E.Testimony.Open");Check(Chapter3Main23Flow.Step==3,"Goal4.WaitForDialogueEnd");CaptureCameraUI("Village_Testimony_UnityCameraUI");yield return Close();Check(Chapter3Main23Flow.Step==4&&!Chapter3Main23Flow.Completed,"Goal4.CompletedWithoutAutoCheckpoint");Checkpoint("Testimony");yield return Continue("Testimony");yield return Wait(.3f);Check(Chapter3Main23Flow.Step==4,"Continue.Testimony");
  yield return Walk(Site(Main23Site.Kind.Checkpoint),"Wheelchair.Checkpoint");yield return Choose(Site(Main23Site.Kind.Checkpoint),1,"Checkpoint.Cancel");Check(!Chapter3Main23Flow.Completed,"Checkpoint.CancelNoComplete");yield return Choose(Site(Main23Site.Kind.Checkpoint),0,"Checkpoint.Register");yield return Close();Check(Chapter3Main23Flow.Completed,"Goal5.Main23Completed");Check(GameSessionData.LastSafeZoneSceneId==Chapter3Main23Flow.Village,"SafeZone.SceneRegistered");Checkpoint("Complete");yield return Continue("Complete");yield return Wait(.4f);Check(Chapter3Main23Flow.Completed&&Chapter3Main22Flow.Completed,"Continue.BothMain22Main23Preserved");
  foreach(int width in new[]{1280,960,1680}){captureWidth=width;Camera.main.aspect=width/720f;At(Vector2.zero);yield return Wait(.6f);CaptureCameraUI("Village_UnityCameraUI_"+width+"x720");var b=Object.FindAnyObjectByType<WorldBounds2D>().Bounds;var c=Camera.main;float half=c.orthographicSize;Check(c.transform.position.x-half*c.aspect>=b.min.x-.01f&&c.transform.position.x+half*c.aspect<=b.max.x+.01f&&c.transform.position.y-half>=b.min.y-.01f&&c.transform.position.y+half<=b.max.y+.01f,"Camera.ViewportInsideBounds."+width);}
  var roles=Object.FindObjectsByType<VillageNpcRole>(FindObjectsSortMode.None);Check(roles.Count(x=>x.Role==VillageNpcRoleType.PetAdoption)==1&&roles.Count(x=>x.Role==VillageNpcRoleType.PetManagement)==1,"Services.PetRolesNoDuplicates");
  yield return Walk(Site(Main23Site.Kind.Party),"Wheelchair.PartyAccess");Check(Site(Main23Site.Kind.Party).TryInteract(),"Party.OpenRequest");yield return Wait(.15f);Check(ProjectLimitless.UI.PartyManagementPresenter.Instance.IsOpen,"Party.ActualUiOpen");yield return Press(UnityEngine.InputSystem.Key.Escape);Check(!WorldModalState.IsOpen,"Keyboard.Escape.PartyCancel");
