  yield return Walk(Site(Main23Site.Kind.LockedNorth),"Wheelchair.LockedNorth");Check(Site(Main23Site.Kind.LockedNorth).TryInteract(),"North.InfoOnly");yield return Close();Check(SceneManager.GetActiveScene().name==Chapter3Main23Flow.Village,"North.NoF2Load");
