  Check(QuestService.GetState("main_24")==QuestState.Locked,"Main24.NotCreated");Check(GameSaveService.CurrentVersion==1,"Save.Version1Preserved");Check(errors.Count==0,"Console.NoRuntimeErrors");File.WriteAllText(Path.Combine(Output,"status.txt"),"PASS");
